# frozen_string_literal: true
# Rails-runner source oracle for synthetic CTE fixture generated by the native test.
# Calls actual plugin preload helpers, PostReactionsQuery, and controller serializer.
require "json"
abort "task DB required" unless ENV["DATABASE_URL"] == "postgres://discourse@127.0.0.1:5499/discourse_development"
abort "task Valkey required" unless ENV["REDIS_URL"] == "redis://127.0.0.1:6399/0"
root = File.expand_path("..", __dir__)
artifact = JSON.parse(File.read(File.join(root, "build/reaction-browser-fixtures-native.json")))
abort "native artifact must be synthetic and read-only" unless artifact["synthetic"] && artifact["read_only"]
fixture = artifact.fetch("source_tables")
connection = ActiveRecord::Base.connection
[Post, PostAction, User, Topic, Category, SharedDraft, DiscourseReactions::Reaction, DiscourseReactions::ReactionUser].each(&:columns)
cte = "WITH " + fixture.map do |table, rows|
  "#{table} AS (SELECT * FROM json_populate_recordset(NULL::public.#{table},#{connection.quote(JSON.generate(rows))}::json))"
end.join(", ") + " "

module ReactionMetadataFixtureDB
  def query(sql, *params)
    prefix = Thread.current[:reaction_metadata_fixture_cte]
    if prefix && sql.lstrip.start_with?("SELECT")
      super(prefix + to_sql(sql, *params))
    else
      super(sql, *params)
    end
  end
end
module ReactionMetadataFixtureAR
  private
  def raw_execute(sql, *args, **kwargs, &block)
    prefix = Thread.current[:reaction_metadata_fixture_cte]
    sql = prefix + sql if prefix && sql.lstrip.start_with?("SELECT")
    super(sql, *args, **kwargs, &block)
  end
end
module ReactionMetadataFixtureSettings
  VALUES = {
    discourse_reactions_enabled: true,
    discourse_reactions_reaction_for_like: "heart",
    discourse_reactions_enabled_reactions: "heart|clap",
    discourse_reactions_excluded_from_like: ""
  }.freeze
  VALUES.each do |name, value|
    define_method(name) do
      overrides = Thread.current[:reaction_metadata_fixture_settings]
      overrides && overrides.key?(name) ? overrides.fetch(name) : super()
    end
  end
end
DB.singleton_class.prepend(ReactionMetadataFixtureDB)
connection.singleton_class.prepend(ReactionMetadataFixtureAR)
SiteSetting.singleton_class.prepend(ReactionMetadataFixtureSettings)
class ReactionMetadataLocalCache
  def initialize
    @entries = {}
  end
  def defer_get_set(key)
    return @entries.fetch(key) if @entries.key?(key)
    @entries[key] = yield
  end
end
module ReactionMetadataEmojiCacheTransport
  def global_emoji_cache
    Thread.current[:reaction_metadata_global_emoji_cache] ||= ReactionMetadataLocalCache.new
  end
  def site_emoji_cache
    Thread.current[:reaction_metadata_site_emoji_cache] ||= ReactionMetadataLocalCache.new
  end
  def standard
    load_standard
  end
  def custom
    load_custom
  end
end
Emoji.singleton_class.prepend(ReactionMetadataEmojiCacheTransport)

source = { "read_only" => true, "synthetic" => true }
ActiveRecord::Base.transaction do
  connection.execute("SET TRANSACTION READ ONLY")
  ActiveRecord::Base.uncached do
    begin
      Thread.current[:reaction_metadata_fixture_settings] = {
        discourse_reactions_enabled: true,
        discourse_reactions_reaction_for_like: "heart",
        discourse_reactions_enabled_reactions: "clap",
        discourse_reactions_excluded_from_like: "excluded"
      }
      metadata_artifact = JSON.parse(File.read(File.join(root, "build/reaction-metadata-fixtures-native.json")))
      original_settings = YAML.safe_load_file(Rails.root.join("plugins/discourse-reactions/config/settings.yml")).fetch("discourse_reactions")
      metadata_artifact.fetch("defaults").each do |key, value|
        raise "native default differs from original plugin settings #{key}" unless original_settings.fetch(key).fetch("default") == value
      end
      source["native_defaults_match_original_settings"] = true
      metadata_cte = "WITH " + metadata_artifact.fetch("tables").map do |table, rows|
        "#{table} AS (SELECT * FROM json_populate_recordset(NULL::public.#{table},#{connection.quote(JSON.generate(rows))}::json))"
      end.join(", ") + " "
      Thread.current[:reaction_metadata_fixture_cte] = metadata_cte
      Thread.current[:reaction_metadata_global_emoji_cache] = ReactionMetadataLocalCache.new
      Thread.current[:reaction_metadata_site_emoji_cache] = ReactionMetadataLocalCache.new
      metadata_post = Post.find(metadata_artifact.fetch("post_id"))
      metadata_preload = DiscourseReactions::ReactionsSerializerHelpers.preload_post_reactions([metadata_post], nil)
      helper = DiscourseReactions::ReactionsSerializerHelpers
      anon_scope = Object.new
      anon_scope.define_singleton_method(:is_anonymous?) { true }
      metadata_source = {
        "reactions" => JSON.parse(JSON.generate(metadata_preload.fetch(:reactions).fetch(metadata_post.id))),
        "current_user_reaction" => helper.current_user_reaction_for_post(metadata_post, anon_scope),
        "reaction_users_count" => metadata_preload.fetch(:reaction_users_count).fetch(metadata_post.id).to_i,
        "current_user_used_main_reaction" => helper.current_user_used_main_reaction_for_post(metadata_post, anon_scope)
      }
      metadata_valid_reactions = DiscourseReactions::Reaction.valid_reactions.to_a
      raise "actual upstream metadata fixture mismatch: #{metadata_source.inspect}" unless metadata_source == metadata_artifact.fetch("metadata")
      raise "actual upstream valid reactions mismatch" unless metadata_valid_reactions == metadata_artifact.fetch("valid_reactions")
      source["metadata_fixture"] = metadata_source.merge("valid_reactions" => metadata_valid_reactions)

      Thread.current[:reaction_metadata_fixture_cte] = cte
      Thread.current[:reaction_metadata_global_emoji_cache] = ReactionMetadataLocalCache.new
      Thread.current[:reaction_metadata_site_emoji_cache] = ReactionMetadataLocalCache.new
      Thread.current[:reaction_metadata_fixture_settings] = {
        discourse_reactions_enabled: true,
        discourse_reactions_reaction_for_like: "heart",
        discourse_reactions_enabled_reactions: "heart|clap",
        discourse_reactions_excluded_from_like: ""
      }
      post = Post.find(artifact.dig("browser", "post_id"))
      preload = DiscourseReactions::ReactionsSerializerHelpers.preload_post_reactions([post], nil)
      helper = DiscourseReactions::ReactionsSerializerHelpers
      main = DiscourseReactions::Reaction.main_reaction_id
      source_metadata = {
        "reactions" => JSON.parse(JSON.generate(preload.fetch(:reactions).fetch(post.id))),
        "reaction_users_count" => preload.fetch(:reaction_users_count).fetch(post.id).to_i,
        "current_user_reaction" => helper.current_user_reaction_for_post(post, anon_scope),
        "current_user_used_main_reaction" => helper.current_user_used_main_reaction_for_post(post, anon_scope),
        "valid_reactions" => DiscourseReactions::Reaction.valid_reactions.to_a
      }
      expected = artifact.dig("browser", "metadata")
      expected_without_valid = expected.except("valid_reactions")
      actual_without_valid = source_metadata.except("valid_reactions")
      raise "actual upstream preload metadata mismatch: #{source_metadata.inspect}" unless actual_without_valid == expected_without_valid
      if expected.key?("valid_reactions")
        raise "actual upstream valid_reactions mismatch" unless source_metadata["valid_reactions"] == expected["valid_reactions"]
      end
      source["metadata"] = source_metadata

      controller = DiscourseReactions::CustomReactionsController.new
      source["endpoints"] = artifact.dig("browser", "endpoints").map do |entry|
        query = DiscourseReactions::PostReactionsQuery.new(
          post: Struct.new(:id).new(post.id), reaction_filter: entry.fetch("reaction_value"),
          limit: entry.fetch("limit"), offset: entry.fetch("page") * entry.fetch("limit"), current_user_id: nil
        )
        query.define_singleton_method(:main_reaction) { main }
        rows = query.rows
        total = query.total
        raw_users = rows.map do |row|
          controller.send(:format_user, row, id: row.id,
            avatar_template: User.avatar_template(row.username, row.uploaded_avatar_id), reaction: row.reaction).transform_keys(&:to_s)
        end
        actual_body = { "users" => raw_users, "total_rows" => total }
        raise "actual upstream users-list body mismatch for #{entry.fetch('path')}" unless actual_body == entry.fetch("body")
        { "path" => entry.fetch("path"), "page" => entry.fetch("page"),
          "limit" => entry.fetch("limit"), "reaction_value" => entry.fetch("reaction_value"),
          "body" => actual_body }
      end
      # Actual plugin-enabled serializer wrappers, not a mutation of settings.
      post_serializer = PostSerializer.new(post, scope: anon_scope, root: false)
      topic_serializer = TopicViewSerializer.new(nil, scope: anon_scope, root: false)
      fields = %w[reactions reaction_users_count current_user_reaction current_user_used_main_reaction]
      raise "enabled source fields missing" unless fields.all? { |field| post_serializer.public_send("include_#{field}?") } && topic_serializer.include_valid_reactions?
      Thread.current[:reaction_metadata_fixture_settings][:discourse_reactions_enabled] = false
      raise "disabled source plugin fields leaked" unless fields.none? { |field| post_serializer.public_send("include_#{field}?") } && !topic_serializer.include_valid_reactions?
      source["disabled_source_serializer_fields_omitted"] = true
      Thread.current[:reaction_metadata_fixture_settings][:discourse_reactions_enabled] = true
      source["source"] = "actual pinned DiscourseReactions::ReactionsSerializerHelpers preload and PostReactionsQuery/controller format_user"
      source["source_sha"] = `git -C #{File.join(root, '..', 'discourse')} rev-parse HEAD`.strip
    ensure
      Thread.current[:reaction_metadata_fixture_cte] = nil
      Thread.current[:reaction_metadata_fixture_settings] = nil
    end
  end
  raise ActiveRecord::Rollback
end
out = File.join(root, "build/reaction-browser-fixtures-source.json")
File.write(out, JSON.generate(source))
puts "PASS actual upstream metadata preload + users-list source oracle (synthetic CTEs; read-only; #{source.fetch('endpoints').length} pages)"
